 return <form className={className} onSubmit={e=>{e.preventDefault();run();}}>{children}{note&&<div className="form-info"><CircleHelp size={17}/>{l(note)}</div>}{error&&<div ref={errorRef} tabIndex={-1}><ErrorNotice error={error}/></div>}<footer className="form-footer"><div>{total?<><span>{l('مجموع سند')}</span><strong className="form-total">{total}</strong></>:<span><Check size={16}/>{l('پیش از ثبت، مقادیر را بررسی کنید.')}</span>}</div><div className="footer-actions">{canDraft&&mode==='post'&&<button className="button secondary" disabled={busy} type="button" onClick={()=>run(true)}>{l('ذخیره پیش‌نویس')}</button>}<button className="button primary" disabled={busy} type="submit">{busy?<LoaderCircle className="spin" size={18}/>:<Check size={18}/>} {l(mode==='approval'?'ارسال برای تأیید':mode==='draft'?'ذخیره پیش‌نویس':'ثبت نهایی')}</button></div></footer></form>;
