function suggestedExpenseNumber(accounts:Row[],group:string){const range=expenseGroups.find(item=>item[0]===group)||expenseGroups[2];const used=new Set(accounts.map(account=>Number(account.number)));let candidate=Number(range[2])+100;while(candidate<=Number(range[3])&&used.has(candidate))candidate+=100;if(candidate<=Number(range[3]))return String(candidate);for(let fallback=Number(range[2]);fallback<=Number(range[3]);fallback++)if(!used.has(fallback))return String(fallback);return '';}
