function JournalForm({submit}:{submit:(p:Row)=>Promise<void>}){const{catalog}=useScope();const[v,setV]=useState<Row>({reason:'',cash_flow_class:'operating',date:today()});const[lines,setLines]=useState<Row[]>([{account:'',debit:'',credit:'0'},{account:'',debit:'0',credit:''}]);const difference=lines.reduce((sum,l)=>sum.plus(decimal(l.debit)).minus(decimal(l.credit)),new Decimal(0));return <FormShell onSubmit={()=>{if(!difference.isZero())throw new Error('جمع بدهکار و بستانکار باید برابر باشد.');return submit({...v,lines});}} note="ثبت مستقیم در حساب‌های کنترلی ممکن است نیاز به فرآیند اصلاح مجاز داشته باشد."><div className="form-grid">{[text('reason','شرح و دلیل اصلاح',true),fixed('cash_flow_class','طبقه جریان نقدی',[{value:'operating',label:'عملیاتی'},{value:'investing',label:'سرمایه‌گذاری'},{value:'financing',label:'تأمین مالی'}])].map(f=><Field key={f.key} field={f} value={v[f.key]} onChange={x=>setV({...v,[f.key]:x})}/>)}</div><LineHeader title={l("ردیف‌های سند")} onAdd={()=>setLines([...lines,{account:'',debit:'0',credit:'0'}])}/>{lines.map((r,i)=><div className="item-editor compact" key={i}><div className="form-grid three"><Field field={fixed(`account-${i}`,'حساب',(catalog.accounts||[]).map((a:Row)=>({value:a.code,label:`${a.code} · ${a.name}`})))} value={r.account} onChange={x=>setLines(updateLine(lines,i,'account',x))}/><Field field={numeric(`debit-${i}`,'بدهکار (AFN)')} value={r.debit} onChange={x=>setLines(updateLine(lines,i,'debit',x))}/><Field field={numeric(`credit-${i}`,'بستانکار (AFN)')} value={r.credit} onChange={x=>setLines(updateLine(lines,i,'credit',x))}/></div><Remove disabled={lines.length<=2} onClick={()=>setLines(lines.filter((_,j)=>j!==i))}/></div>)}<div className="sale-balance"><span>{l("اختلاف بدهکار و بستانکار")}</span><strong className={!difference.isZero()?'text-red':''}>{money(difference.toString())}</strong></div></FormShell>}
function CompletionForm({documents,submit,initial={}}:{initial?:Row,documents:Row[],submit:(p:Row)=>Promise<void>}){
 const{catalog}=useScope();const[v,setV]=useState<Row>({date:today(),batch:initial.batch||'',warehouse:initial.warehouse||'',product:initial.product||'',quantity:'',count:'1',length_mm:'2000',width_mm:'1000',height_mm:'1000',allocated_cost:'',abnormal_loss:'0',status:'ready'});const p=(catalog.products||[]).find((r:Row)=>r.id===Number(v.product));
 const fields=[currentDate(),select('batch','بچ در جریان',documents.filter(d=>d.kind==='production_start'),true,'number'),select('warehouse','انبار خروجی',catalog.warehouses||[]),select('product','محصول خروجی',(catalog.products||[]).filter((r:Row)=>r.kind==='finished')), ...(p?.unit==='cm'?[numeric('count','تعداد بلوک‌های هم‌اندازه'),numeric('length_mm','طول هر بلوک (mm)'),numeric('width_mm','عرض هر بلوک (mm)'),numeric('height_mm','ارتفاع هر بلوک (mm)')]:[numeric('quantity',`${l('مقدار خروجی')} (${p?.unit||l('واحد')})`)]),numeric('allocated_cost','بهای تخصیص به این تکمیل (خالی = تمام WIP)',false),numeric('abnormal_loss','زیان غیرعادی تأییدشده (AFN)',true,'0'),fixed('status','وضعیت خروجی',[{value:'ready',label:'آماده فروش'},{value:'hold',label:'تحت بررسی کیفیت'},{value:'curing',label:'در حال عمل‌آوری'}])];
 return <FormShell onSubmit={()=>{const count=Number(v.count);if(p?.unit==='cm'&&(!Number.isInteger(count)||count<1||count>1000))throw new Error('تعداد بلوک باید عدد صحیح بین ۱ تا ۱۰۰۰ باشد.');const output=p?.unit==='cm'?{product:v.product,blocks:Array.from({length:count},()=>({length_mm:v.length_mm,width_mm:v.width_mm,height_mm:v.height_mm,status:v.status}))}:{product:v.product,quantity:v.quantity};return submit(valuesToPayload({date:v.date,batch:v.batch,warehouse:v.warehouse,allocated_cost:v.allocated_cost,abnormal_loss:v.abnormal_loss,outputs:[output]}));}} note="برای بلوک‌های با ابعاد متفاوت، تکمیل‌های جدا ثبت کنید و بهای هر بخش را مشخص سازید. هزینه خروجی از WIP همان بچ کسر می‌شود."><div className="form-grid">{fields.map(f=><Field key={f.key} field={f} value={v[f.key]} onChange={x=>setV({...v,[f.key]:x})}/>)}</div></FormShell>;
}
function TransferReceiveForm({documents,submit,resolve}:{documents:Row[],submit:(p:Row)=>Promise<void>,resolve:boolean}){
 const{catalog}=useScope();const[v,setV]=useState<Row>({date:today(),transfer:'',resolution:'shortage',reason:''});const[lines,setLines]=useState<Row[]>([]);const choose=(id:string)=>{setV({...v,transfer:id});const d=documents.find(d=>d.id===Number(id));const original=d?.result?.lines||[];setLines(original.map((l:Row)=>{const resolved=documents.filter(r=>r.reference===d?.id&&['transfer_receive','transfer_resolve'].includes(r.kind)).flatMap(r=>r.result?.lines||[]).filter((r:Row)=>r.index===l.index).reduce((sum:number,r:Row)=>sum+Number(r.quantity),0);return {...l,quantity:String(Math.max(Number(l.quantity)-resolved,0))};}));};
 return <FormShell onSubmit={()=>{const selected=lines.filter(l=>decimal(l.quantity).gt(0)).map(l=>({index:l.index,quantity:l.quantity}));if(!selected.length)throw new Error('مقدار مثبت برای حداقل یک ردیف وارد کنید.');return submit({...v,lines:selected});}} note="مقدار هر دریافت می‌تواند جزئی باشد. هر بلوک فیزیکی باید به صورت کامل تأیید شود؛ ردیف‌های ۰ دریافت نمی‌شوند."><div className="form-grid"><Field field={currentDate()} value={v.date} onChange={x=>setV({...v,date:x})}/><Field field={select('transfer','سند انتقال',documents.filter(d=>d.kind==='transfer_dispatch'),true,'number')} value={v.transfer} onChange={choose}/>{resolve&&<><Field field={fixed('resolution','نوع حل مغایرت',[{value:'shortage',label:'کسری تأییدشده'},{value:'damage',label:'آسیب / ضایعات'},{value:'return',label:'برگشت به مبدأ'}])} value={v.resolution} onChange={x=>setV({...v,resolution:x})}/><Field field={text('reason','دلیل و تأیید مغایرت',true)} value={v.reason} onChange={x=>setV({...v,reason:x})}/></>}</div>{lines.map((l,i)=><div className="item-editor compact" key={i}><span className="transfer-line-name">{catalog.products?.find((p:Row)=>p.id===l.product)?.name||l.product}</span><Field field={numeric(`receive-${i}`,'مقدار این مرحله')} value={l.quantity} onChange={x=>setLines(updateLine(lines,i,'quantity',x))}/></div>)}</FormShell>;
}
function OrderForm({documents,submit,quotation,initial={}}:{documents:Row[],submit:(p:Row)=>Promise<void>,quotation:boolean,initial?:Row}){
 const{catalog,business}=useScope();const[v,setV]=useState<Row>({date:today(),warehouse:'',party:'',quotation:initial.quotation||''});const[lines,setLines]=useState<Row[]>([{product:'',quantity:'',unit_price:'',length_mm:'',width_mm:''}]);
 const source=documents.find(d=>d.id===Number(v.quotation));
 const choose=(id:string)=>{const doc=documents.find(d=>d.id===Number(id));if(!doc){setV(previous=>({...previous,quotation:''}));setLines(previous=>previous.map(line=>({...line,quotation_index:undefined})));return;}setV(previous=>({...previous,quotation:id,party:doc.party,warehouse:doc.warehouse}));setLines(sourceLines(doc).filter(line=>decimal(line.remaining_quantity).gt(0)).map(line=>({...line,quantity:line.remaining_quantity,quotation_index:line.index})));};
 const initialSource=documents.find(d=>d.id===Number(initial.quotation));
 useEffect(()=>{if(initial.quotation&&initialSource)choose(String(initial.quotation));},[initial.quotation,initialSource?.id]);
 const total=lines.reduce((sum,line)=>sum.plus(decimal(line.quantity).mul(decimal(line.unit_price))),new Decimal(0));
 return <FormShell onSubmit={()=>submit({...valuesToPayload(v),lines:lines.map(valuesToPayload)})} total={money(total.toString())} note="سفارش و پیش‌فاکتور، موجودی یا دفتر کل را تغییر نمی‌دهند. تحویل و فروش واقعی به صورت جداگانه ثبت می‌شود.">
 {!quotation&&<Field field={{...select('quotation','پیش‌فاکتور مرتبط',documents.filter(d=>d.kind==='quotation'&&d.state==='posted'&&d.sales_flow?.can_continue!==false),false,'number'),help:'انتخاب سند، مشتری، انبار، نرخ و اقلام مانده را پر می‌کند.'}} value={v.quotation} onChange={choose}/>}
 {source&&<div className="sales-source-note"><strong><bdi>{source.number}</bdi></strong><span>{l('اطلاعات مشتری و اقلام از سند قبلی گرفته می‌شود. قبل از ثبت بررسی کنید.')}</span><button type="button" className="text-link" onClick={()=>choose('')}>{l('انصراف از سند مرتبط')}</button></div>}
 <div className="form-grid">{[currentDate(),select('warehouse','انبار',catalog.warehouses||[]),select('party','مشتری',(catalog.parties||[]).filter((p:Row)=>p.kind==='customer'))].map(f=><Field key={f.key} field={f} value={v[f.key]} onChange={x=>setV({...v,[f.key]:x})}/>)}</div>
 {hasPermission(business,'sales.credit_override')&&<Field field={{key:'credit_override_reason',label:'دلیل استثنای نسیه'}} value={v.credit_override_reason} onChange={x=>setV({...v,credit_override_reason:x})}/>}<LineHeader title={l("اقلام سفارش")} onAdd={()=>setLines([...lines,{product:'',quantity:'',unit_price:'',length_mm:'',width_mm:''}])}/>{lines.map((r,i)=>{const p=(catalog.products||[]).find((p:Row)=>p.id===Number(r.product));return <div className="item-editor" key={i}><div className="item-editor-head"><span>{number(i+1)}</span><strong>{money(decimal(r.quantity).mul(decimal(r.unit_price)).toString())}</strong><Remove disabled={lines.length===1} onClick={()=>setLines(lines.filter((_,j)=>i!==j))}/></div><div className="form-grid"><Field field={select(`order-product-${i}`,'محصول',(catalog.products||[]).filter((p:Row)=>p.kind!=='raw'))} value={r.product} onChange={x=>{const p=(catalog.products||[]).find((p:Row)=>p.id===Number(x));setLines(lines.map((a,j)=>j===i?{...a,product:x,unit_price:p?.price||'0'}:a));}}/><Field field={numeric(`order-qty-${i}`,`${l('مقدار')} (${p?.unit||l('واحد')})`)} value={r.quantity} onChange={x=>setLines(updateLine(lines,i,'quantity',x))}/><Field field={numeric(`order-price-${i}`,'نرخ هر واحد (AFN)')} value={r.unit_price} onChange={x=>setLines(updateLine(lines,i,'unit_price',x))}/>{p?.unit==='cm'&&<><Field field={numeric(`order-length-${i}`,'طول ورق (mm)')} value={r.length_mm} onChange={x=>setLines(updateLine(lines,i,'length_mm',x))}/><Field field={numeric(`order-width-${i}`,'عرض ورق (mm)')} value={r.width_mm} onChange={x=>setLines(updateLine(lines,i,'width_mm',x))}/></>}</div></div>;})}</FormShell>;
}

function ReceiptForm({documents,submit,initial={}}:{documents:Row[],submit:(p:Row)=>Promise<void>,initial?:Row}){
 const{catalog,locationId}=useScope();const[v,setV]=useState<Row>({date:today(),invoice:initial.invoice||'',party:initial.party||'',amount:initial.amount||'',cash_account:'CASH',location:initial.location||locationId||(catalog.locations?.length===1?catalog.locations[0].id:''),reference:''});
 const invoice=documents.find(d=>d.id===Number(v.invoice));
 const choose=(id:string)=>{const doc=documents.find(d=>d.id===Number(id));setV(previous=>({...previous,invoice:id,...(doc?{party:doc.party,location:doc.location,amount:doc.balance}:{})}));};
 const initialSource=documents.find(d=>d.id===Number(initial.invoice));
 useEffect(()=>{if(initial.invoice&&initialSource)setV(previous=>({...previous,invoice:initial.invoice,party:initialSource.party,location:initialSource.location,amount:initial.amount||initialSource.balance}));},[initial.invoice,initialSource?.id]);
 const remaining=invoice?Decimal.max(decimal(invoice.balance).minus(decimal(v.amount)),0):new Decimal(0);
 return <FormShell onSubmit={()=>submit(valuesToPayload(v))} note="ثبت این دریافت فروش جدید ایجاد نمی‌کند.">
 <Field field={{...select('invoice','بل فروش',documents.filter(d=>['sale','opening_receivable'].includes(d.kind)&&Number(d.balance)>0),false,'number'),help:'مبلغ دریافت از مانده بل گرفته می‌شود؛ برای دریافت قسمی آن را تغییر دهید.'}} value={v.invoice} onChange={choose}/>
 {invoice?<><div className="sales-source-note"><strong><bdi>{invoice.number}</bdi> · {invoice.party_name||catalog.parties?.find((p:Row)=>p.id===invoice.party)?.name}</strong><span>{l('مبلغ دریافت از مانده بل گرفته می‌شود؛ برای دریافت قسمی آن را تغییر دهید.')}</span></div><div className="sales-receipt-summary"><div><span>{l('مبلغ کل')}</span><strong>{money(invoice.amount)}</strong></div><div><span>{l('مانده قابل دریافت')}</span><strong>{money(invoice.balance)}</strong></div><div><span>{l('مانده پس از این دریافت')}</span><strong>{money(remaining.toString())}</strong></div></div></>:<Field field={select('party','حساب مشتری (برای پیش‌پرداخت)',(catalog.parties||[]).filter((p:Row)=>p.kind==='customer'))} value={v.party} onChange={x=>setV({...v,party:x})}/>}
 <div className="form-grid">{[currentDate(),select('location','موقعیت',catalog.locations||[]),numeric('amount','مبلغ دریافت (AFN)'),fixed('cash_account','حساب دریافت',cashOptions),text('reference','مرجع / شماره رسید')].map(f=><Field key={f.key} field={f} value={v[f.key]} onChange={x=>setV({...v,[f.key]:x})}/>)}</div>
 {invoice&&decimal(v.amount).gt(decimal(invoice.balance))&&<p className="form-info">{l('دریافت اضافه به اعتبار مشتری می‌رود.')}</p>}
 </FormShell>;
}

function OpeningStockForm({submit}:{submit:(p:Row)=>Promise<void>}){
 const{catalog}=useScope();const[v,setV]=useState<Row>({date:today(),warehouse:'',product:'',quantity:'',value:'',count:'1',length_mm:'2000',width_mm:'1000',height_mm:'1000',reason:''});const product=catalog.products?.find((p:Row)=>p.id===Number(v.product));
 const fields=[currentDate(),select('warehouse','انبار',catalog.warehouses||[]),select('product','محصول / مواد',catalog.products||[]),numeric('value','ارزش دفتری کل آغازین (AFN)'),...(product?.unit==='cm'?[numeric('count','تعداد بلوک هم‌اندازه'),numeric('length_mm','طول بلوک (mm)'),numeric('width_mm','عرض بلوک (mm)'),numeric('height_mm','ارتفاع قابل فروش (mm)')]:[numeric('quantity','مقدار آغازین در واحد محصول')]),text('reason','مرجع شمارش و تأیید مانده آغازین',true)];
 return <FormShell onSubmit={()=>{const count=Number(v.count);if(product?.unit==='cm'&&(!Number.isInteger(count)||count<1||count>1000))throw new Error('تعداد بلوک باید عدد صحیح بین ۱ تا ۱۰۰۰ باشد.');return submit({date:v.date,warehouse:v.warehouse,reason:v.reason,lines:[{product:v.product,value:v.value,...(product?.unit==='cm'?{blocks:Array.from({length:count},()=>({length_mm:v.length_mm,width_mm:v.width_mm,height_mm:v.height_mm}))}:{quantity:v.quantity})}]});}} note="فقط مانده واقعی در تاریخ شروع را ثبت کنید. خرید جدید را از بخش خرید ثبت کنید. این عملیات با حساب سرمایه آغازین تطبیق می‌شود و نباید دوباره برای همان موجودی اجرا شود."><div className="form-grid">{fields.map(f=><Field key={f.key} field={f} value={v[f.key]} onChange={x=>setV({...v,[f.key]:x})}/>)}</div></FormShell>
}

function BankReconcileForm({submit}:{submit:(p:Row)=>Promise<void>}){
 const{catalog,businessId}=useScope();const instruments=useResource('/api/money-instruments/?choices=1');const[v,setV]=useState<Row>({date:today(),location:'',bank_instrument:'',through_date:today(),statement_balance:''});const[selected,setSelected]=useState<number[]>([]);const query=useQuery({queryKey:['bank-entries',businessId,v.location,v.bank_instrument,v.through_date],queryFn:()=>api.get(`/api/bank-entries/?location=${v.location}&through_date=${v.through_date}${v.bank_instrument?`&bank_instrument=${v.bank_instrument}`:''}`),enabled:!!v.location});useEffect(()=>setSelected([]),[v.location,v.bank_instrument,v.through_date]);const entries=rows(query.data);const cleared=entries.filter(e=>selected.includes(e.id)).reduce((total,e)=>total.plus(decimal(e.amount)),new Decimal(0));
 const fields=[currentDate(),select('location','موقعیت حساب بانک',catalog.locations||[]),{key:'through_date',label:'تا تاریخ صورت‌حساب',type:'date' as const,required:true},select('bank_instrument','حساب بانکی مستقل',(instruments.data?.results||[]).filter((r:Row)=>r.kind==='BANK'&&String(r.location)===String(v.location)),false),numeric('statement_balance','مانده صورت‌حساب بانک (AFN)')];
 return <FormShell onSubmit={()=>{if(!cleared.equals(decimal(v.statement_balance)))throw new Error('مجموع ردیف‌های انتخاب‌شده باید با مانده صورت‌حساب برابر باشد.');return submit({...v,account:'BANK',entry_ids:selected});}} note="فقط تراکنش‌هایی را علامت بزنید که در صورت‌حساب بانک دیده می‌شوند. مانده آغازین بانک را نیز در صورت نیاز انتخاب کنید."><div className="form-grid">{fields.map(field=><Field key={field.key} field={field} value={v[field.key]} onChange={value=>{setV({...v,[field.key]:value});if(field.key==='location'||field.key==='through_date')setSelected([]);}}/>)}</div>{query.isError&&<ErrorNotice error={query.error}/>}<div className="table-wrap"><table><thead><tr><th>{l("تطبیق")}</th><th>{l("تاریخ")}</th><th>{l("سند")}</th><th>{l("بدهکار")}</th><th>{l("بستانکار")}</th></tr></thead><tbody>{entries.map(e=><tr key={e.id}><td><input type="checkbox" aria-label={`${l('تطبیق')} ${e.number}`} checked={selected.includes(e.id)} onChange={event=>setSelected(event.target.checked?[...selected,e.id]:selected.filter(id=>id!==e.id))}/></td><td>{formatCalendarDate(e.date)}</td><td>{e.number}</td><td>{money(e.debit)}</td><td>{money(e.credit)}</td></tr>)}</tbody></table></div><div className="sale-balance"><span>{l("مانده تراکنش‌های تطبیق‌شده")}</span><strong>{money(cleared.toString())}</strong></div></FormShell>
}
function PayrollForm({submit,initial={}}:{submit:(payload:Row)=>Promise<void>,initial?:Row}){
 const{catalog}=useScope();const defaultCalendar=businessCalendar(catalog.business?.settings,today());const[v,setV]=useState<Row>({date:today(),employee:initial.employee||'',period_calendar:defaultCalendar,period:businessPeriodFor(today(),defaultCalendar),week_start_date:'',gross:'',days:'',hours:'',project_reference:'',reason:'',expense_account:'SALARY',line:'shared'});const[busy,setBusy]=useState(false);const[error,setError]=useState('');const employee=catalog.employees?.find((r:Row)=>String(r.id)===String(v.employee));
 const weekly=employee?.kind==='weekly';const window=useResource(`/api/business-periods/?calendar=${v.period_calendar}&period=${v.period}`,!weekly&&!!v.period);const fields:FieldDef[]=[currentDate(),select('employee','کارمند',(catalog.employees||[]).filter((r:Row)=>r.active)),...(weekly?[{key:'week_start_date',label:'تاریخ آغاز هفته معاش',type:'date' as const,required:true}]:[fixed('period_calendar','تقویم محاسبه معاش',[{value:'jalali',label:'هجری شمسی'},{value:'gregorian',label:'میلادی'}]),{key:'period',label:'ماه معاش',required:true}]),numeric('gross','مبلغ ناخالص (اختیاری، محاسبه از نرخ)',false),...(!employee||(['daily','part_time'].includes(employee.kind)&&employee.terms?.rate_basis!=='hour')?[numeric('days','روزهای حضور تأییدشده',false)]:[]),...(!employee||employee.kind==='hourly'||employee.terms?.rate_basis==='hour'?[numeric('hours','ساعت‌های حضور تأییدشده',false)]:[]),...(employee?.kind==='project'?[text('project_reference','مرجع تأیید پروژه / تحویل کار',true)]:[]),text('reason','دلیل مبلغ ناخالص تأییدشده',weekly&&!!v.gross),fixed('expense_account','حساب کار',[{value:'SALARY',label:'مصرف معاش اداری'},{value:'LABOR_CLEARING',label:'کار تولید برای جذب در بچ'}]),fixed('line','خط محصول',[{value:'shared',label:'عمومی / اداری'},{value:'sponge',label:'اسفنج'},{value:'adhesive',label:'چسپ'}])];
 return <form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{const payload=valuesToPayload(v);if(weekly){delete payload.period;delete payload.period_calendar;delete payload.days;delete payload.hours;}else delete payload.week_start_date;if(employee?.kind!=='project')delete payload.project_reference;await submit(payload);}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy(false);}}}><div className="form-grid">{fields.map(f=>f.key==='period'?<BusinessPeriodInput key={f.key} calendar={v.period_calendar} value={v.period} onChange={period=>setV({...v,period})}/>:<Field key={f.key} field={f} value={v[f.key]} onChange={value=>setV({...v,[f.key]:value,...(f.key==='employee'?{days:'',hours:'',gross:'',project_reference:''}:f.key==='period_calendar'?{period:businessPeriodFor(v.date,value)}:{})})}/>)}</div>{weekly?<p className="form-info">{l('هفته معاش هفت روز است؛ ثبت در ختم هفته یا پس از آن انجام می‌شود. هفته‌های تکراری ثبت نمی‌شوند.')}</p>:window.data?.earning_window?.valid?<p className="form-info">{l('دوره واقعی معاش')}: {formatCalendarDate(window.data.earning_window.first)} — {formatCalendarDate(window.data.earning_window.last)} · {l('تقویم نمایشی، قرارداد معاش را تغییر نمی‌دهد.')}</p>:window.data?.earning_window?.error?<ErrorNotice error={window.data.earning_window.error}/>:null}{!weekly&&window.isError&&<ErrorNotice error={window.error}/>} {error&&<ErrorNotice error={error}/>}<footer className="form-footer"><span>{l('مقادیر را پیش از ثبت بررسی کنید')}</span><button type="submit" className="button primary" disabled={busy||(!weekly&&(window.isLoading||window.isError||window.data?.earning_window?.valid===false))}>{l('ثبت نهایی')}</button></footer></form>;
}
